import { editingSampleRate } from './audio-format.mjs';
export class Player {
  constructor(onState){this.onState=onState;this.context=null;this.node=null;this.offset=0;this.playing=false;this.volume=.7;this.jobs=new Map();this.cache=new Map();this.worker=new Worker(new URL('./audio-worker.mjs',import.meta.url),{type:'module'});this.worker.onmessage=({data})=>{const job=this.jobs.get(data.id);if(!job)return;this.jobs.delete(data.id);data.error?job.reject(new Error(data.error)):job.resolve(data);};this.worker.onerror=()=>{for(const job of this.jobs.values())job.reject(new Error('音频处理失败，请刷新后重试。'));this.jobs.clear();};}
  async init(){if(!this.context){this.context=new AudioContext();this.output=this.context.createGain();this.output.gain.value=this.volume;this.output.connect(this.context.destination);}if(this.context.state==='suspended')await this.context.resume();}
  async render(version){const key=JSON.stringify(version);if(this.cache.has(key))return this.cache.get(key);const assets={};for(const track of version.tracks){if(track.assetId&&!assets[track.assetId]){const asset=await get('assets',track.assetId);if(!asset)throw new Error(`找不到音轨「${track.name}」，请重新导入。`);assets[track.assetId]={channels:asset.channels,sampleRate:asset.sampleRate||SAMPLE_RATE};}}
    const sampleRate=Math.max(version.sampleRate||SAMPLE_RATE,...Object.values(assets).map(a=>a.sampleRate));
    for(const asset of Object.values(assets))if(asset.sampleRate!==sampleRate){const offline=new OfflineAudioContext(asset.channels.length,Math.ceil(asset.channels[0].length*sampleRate/asset.sampleRate),sampleRate);const buffer=offline.createBuffer(asset.channels.length,asset.channels[0].length,asset.sampleRate);asset.channels.forEach((c,i)=>buffer.copyToChannel(c,i));const node=offline.createBufferSource();node.buffer=buffer;node.connect(offline.destination);node.start();const converted=await offline.startRendering();asset.channels=Array.from({length:converted.numberOfChannels},(_,i)=>converted.getChannelData(i).slice());asset.sampleRate=sampleRate;}
    const id=uid();const response=await new Promise((resolve,reject)=>{this.jobs.set(id,{resolve,reject});this.worker.postMessage({id,version:{...version,sampleRate},assets});});this.cache.set(key,response);while(this.cache.size>3)this.cache.delete(this.cache.keys().next().value);return response;}
  get position(){return this.playing?this.offset+(this.context.currentTime-this.startedAt):this.offset;}
  pause(){this.serial=(this.serial||0)+1;if(this.playing){this.offset=this.position;this.playing=false;if(this.node){this.node.onended=null;this.node.stop();this.node.disconnect();this.node=null;}}this.onState?.();}
  stop(){this.pause();this.offset=this.version?.trim.start||0;this.onState?.();}
  async play(version,position){this.pause();const serial=this.serial;await this.init();const {mix}=await this.render(version);if(serial!==this.serial)return;this.version=version;const buffer=this.context.createBuffer(2,mix.left.length,mix.sampleRate);buffer.copyToChannel(mix.left,0);buffer.copyToChannel(mix.right,1);let offset=position??this.offset;offset=Math.max(version.trim.start,offset);if(offset>=version.trim.end-.02)offset=version.trim.start;this.offset=offset;this.node=this.context.createBufferSource();this.node.buffer=buffer;this.node.connect(this.output);this.node.onended=()=>{this.playing=false;this.offset=version.trim.start;this.node?.disconnect();this.node=null;this.onState?.();};this.startedAt=this.context.currentTime;this.playing=true;this.node.start(0,offset,version.trim.end-offset);this.onState?.();}
  setVolume(value){this.volume=value;if(this.output)this.output.gain.setTargetAtTime(value,this.context.currentTime,.025);}
  async decode(file){let buffer;try{const original=await file.arrayBuffer(),rate=editingSampleRate(original);const context=new OfflineAudioContext(2,1,rate);buffer=await context.decodeAudioData(original);}catch{throw new Error('无法读取这个音频，请使用有效的 WAV、MP3、M4A 或 OGG 文件。');}if(buffer.duration>300)throw new Error('音频超过 5 分钟，请先裁剪。');if(buffer.duration<.5)throw new Error('音频至少需要 0.5 秒。');if(buffer.numberOfChannels>2)throw new Error('当前支持单声道或立体声音频，请先将多声道音频导出为立体声。');return {duration:buffer.duration,channels:Array.from({length:buffer.numberOfChannels},(_,i)=>buffer.getChannelData(i).slice()),sampleRate:buffer.sampleRate,originalBlob:file,originalName:file.name};}
  async wav(version){const {mix}=await this.render(version);if(mix.clippedSamples)throw new Error('当前混音有过载，请降低音轨音量后再导出。原始文件仍可直接下载。');return new Blob([encodeWav(mix,version.trim.start,version.trim.end,24)],{type:'audio/wav'});}
}
